-- Remove the four remaining demo products from V3__seed_data.sql:
--   LEH-BRD-0001  Crimson Velvet Bridal Lehenga Set
--   KRT-ANK-0001  Floral Georgette Anarkali Kurta Set
--   SUT-EMB-0001  Embroidered Chanderi Suit Fabric
--   LEH-PTY-0001  Sequined Georgette Party Lehenga
--
-- The seed data created demo orders (KCH-2026-000002, KCH-2026-000003)
-- that reference these product listings, so the order chain must be
-- deleted first to satisfy the order_items_listing_id_fkey constraint.

-- 1. Packaging for the two demo orders
DELETE FROM packaging WHERE order_id IN (
    '5eed0000-0000-0000-001c-000000000002',
    '5eed0000-0000-0000-001c-000000000003'
);

-- 2. Order items that reference the demo listings
DELETE FROM order_items WHERE order_id IN (
    '5eed0000-0000-0000-001c-000000000002',
    '5eed0000-0000-0000-001c-000000000003'
);

-- 3. The two demo orders themselves
DELETE FROM orders WHERE id IN (
    '5eed0000-0000-0000-001c-000000000002',
    '5eed0000-0000-0000-001c-000000000003'
);

-- 4. Product listings
